let slideIndex = 1,
  autoSlideTimer;
document.addEventListener("DOMContentLoaded", function () {
  showSlides(slideIndex), startAutoSlide();
});
function plusSlides(n) {
  showSlides((slideIndex += n)), resetAutoSlide();
}
function currentSlide(n) {
  showSlides((slideIndex = n)), resetAutoSlide();
}
function showSlides(n) {
  let e = document.getElementsByClassName("mySlides"),
    t = document.getElementsByClassName("dot"),
    l = document.querySelector(".slides-wrapper");
  if (!l || 0 === e.length) return;
  n > e.length && (slideIndex = 1), n < 1 && (slideIndex = e.length);
  let s = -((slideIndex - 1) * (100 / e.length));
  if (((l.style.transform = `translateX(${s}%)`), t.length > 0)) {
    for (let e = 0; e < t.length; e++)
      t[e].className = t[e].className.replace(" active", "");
    t[slideIndex - 1] && (t[slideIndex - 1].className += " active");
  }
}
function autoSlide() {
  slideIndex++, showSlides(slideIndex);
}
function startAutoSlide() {
  autoSlideTimer = setInterval(autoSlide, 6e3);
}
function resetAutoSlide() {
  clearInterval(autoSlideTimer), startAutoSlide();
}
document.addEventListener("DOMContentLoaded", function () {
  const e = document.querySelector(".slideshow-container");
  e &&
    (e.addEventListener("mouseenter", function () {
      clearInterval(autoSlideTimer);
    }),
    e.addEventListener("mouseleave", function () {
      startAutoSlide();
    }));
});
